content.arguments:
{"description":"抓取 gcsim 夜兰源码并过滤关键行","command":"$ErrorActionPreference='Continue'
[Console]::OutputEncoding=[System.Text.Encoding]::UTF8
$dir='./'
"DIR_EXISTS: " + (Test-Path $dir)
"PARENT_EXISTS: " + (Test-Path (Split-Path $dir))
$base='http./'
$files=@('yelan.go','skill.go','burst.go','chargeattack.go','talent.go','cons.go','constellation.go')
foreach($f in $files){
  try{
    $r=Invoke-WebRequest -UseBasicParsing -Uri ($base+$f) -TimeoutSec 45
    "`n===== $f (HTTP $($r.StatusCode), $($r.Content.Length) chars) ====="
    $i=0
    foreach($line in ($r.Content -split "`n")){
      $i++
      if($line -match '(?i)desc|hp|Duration|Interval|stack|[0-9]+\.[0-9]+|%|CD|mult'){ "{0,5}| {1}" -f $i,$line.TrimEnd() }
    }
  }catch{ "`n===== $f FAIL: $($_.Exception.Message)" }
}"}

