{"description":"用 GitHub API 探测 gcsim 夜兰目录真实路径","command":"[Console]::OutputEncoding=[System.Text.Encoding]::UTF8
$ua=@{'User-Agent'='dsh-scout'}
$try=@(
 'http./',
 'http./',
 'http./'
)
foreach($u in $try){
  foreach($p in @($null,'htt./')){
    $tag = if($p){"PROXY"}else{"DIRECT"}
    try{
      $r=Invoke-WebRequest -UseBasicParsing -Uri $u -Headers $ua -TimeoutSec 30 -Proxy $p
      "== $tag OK $u ($($r.Content.Length) chars)"
      $j=$r.Content | ConvertFrom-Json
      if($j -is [array]){ "  names: " + (($j | ForEach-Object { $_.name }) -join ', ') }
      else { "  default_branch: " + $j.default_branch + " | full_name: " + $j.full_name }
      break
    }catch{ "== $tag FAIL $u -> $($_.Exception.Message)" }
  }
}"}

